 92	/**
 93	 * Allowlist for WP IDs and queue entry IDs: must start with alnum, then word chars or hyphens.
 94	 * Note: `\w` includes underscore intentionally — WP IDs (`WP-001`) and queue entry IDs may
 95	 * contain underscores in future formats. This is permissive by design.
 96	 */
 97	const SAFE_ID_PATTERN = /^[A-Za-z0-9][\w-]*$/;
 98	
 99	/**
100	 * Guards against path-traversal attacks on the project slug URL parameter.

101	 *
102	 * Rejects any slug that does not satisfy the safe-slug rules
103	 * (lowercase alphanumeric + hyphens, must start with an alphanumeric character).
104	 * This reuses the same slug format enforced on project creation and rename,
105	 * ensuring only lowercase alphanumeric characters and hyphens are accepted —
106	 * eliminating path separators and traversal sequences by design.
107	 *
108	 * @param slug - The raw slug string extracted from the request URL.
109	 */
110	function assertSafeSlug(slug: string): void {
111	  if (!assertSafeSegment(slug)) {
112	    notFound(`Invalid project slug: '${slug}'.`);
113	  }
114	}
115	
116	/**
117	 * Guards against path-traversal attacks on the work-package ID URL parameter.
118	 *
119	 * Rejects any wpId that does not match {@link SAFE_ID_PATTERN}
120	 * (`/^[A-Za-z0-9][\w-]*$/`). Requires an alphanumeric first character,
121	 * blocking `..`, `.`, and all path separators by design.
122	 *
123	 * @param wpId - The raw work-package ID string extracted from the request URL.
124	 */
125	function assertSafeWpId(wpId: string): void {
126	  if (!wpId || !SAFE_ID_PATTERN.test(wpId)) {
127	    notFound(`Invalid work-package ID: '${wpId}'.`);
128	  }
129	}
130	
131	/**
132	 * Guards against path-traversal attacks on the orchestrator queue entry ID
133	 * URL parameter.
134	 *
135	 * Rejects any id that does not match {@link SAFE_ID_PATTERN}
136	 * (`/^[A-Za-z0-9][\w-]*$/`). Requires an alphanumeric first character,
137	 * blocking `..`, `.`, and all path separators by design.
138	 *
139	 * @param id - The raw queue entry ID string extracted from the request URL.
140	 */
141	function assertSafeQueueId(id: string): void {
142	  if (!id || !SAFE_ID_PATTERN.test(id)) {
143	    notFound(`Invalid queue entry ID: '${id}'.`);
144	  }
145	}
