147	/**
148	 * Resolves a LedgerStore for URL-parameter-driven handlers.
149	 *
150	 * Locates the namespaced storage directory via resolveProjectDir(), reads
151	 * .meta.json for plan_path, and constructs a LedgerStore from it. Callers
152	 * must validate `slug` (via assertSafeSlug) before calling. If `repoName` is
153	 * provided, it is validated here via assertSafeSlug before being joined with
154	 * `slug` to form a qualified `{repo}/{slug}` lookup.
155	 *
156	 * @remarks **Security contract — AMBIGUOUS → NOT_FOUND downgrade:**
157	 * When `resolveProjectDir()` throws an AMBIGUOUS error (multiple repos contain
158	 * this slug), this function intentionally downgrades it to the same NOT_FOUND
159	 * ApiError used for a missing project. This prevents callers from learning
160	 * that a slug exists in any repository (cross-namespace existence leak).
161	 * The inline comment in the catch block documents the downgrade decision;
162	 * do not restore the original AMBIGUOUS message without a security review.
163	 *
164	 * @remarks **Diagnostic logging — metadata read failures:**
165	 * When reading `.meta.json` fails (e.g. file missing, corrupt JSON, schema
166	 * mismatch), the second catch block logs a structured message to `stderr`
167	 * before calling `notFound()`. The log line includes the slug, optional repo
168	 * name, and the error message so operators can diagnose storage issues without
169	 * enabling debug-level verbosity. The function's externally-visible behaviour
170	 * is unchanged: callers always receive a NOT_FOUND response. Do not remove the
171	 * `stderr.write` call — it is the only signal that distinguishes a missing
172	 * project from a corrupted metadata file in production logs.
173	 *
174	 * @throws ApiError NOT_FOUND when the project cannot be located, is ambiguous
175	 *   across namespaces, or has no metadata.
176	 */
177	async function resolveProjectStore(
178	  ledgerRoot: string,
179	  slug: string,
180	  repoName?: string
181	): Promise<LedgerStore> {
182	  if (repoName !== undefined) {
183	    assertSafeSlug(repoName);
184	  }
185	  const slugOrQualified = repoName !== undefined ? `${repoName}/${slug}` : slug;
186	
187	  let storageDir: string;
188	  try {
189	    storageDir = await resolveProjectDir(slugOrQualified, ledgerRoot);
190	  } catch (err) {
191	    const msg = err instanceof Error ? err.message : String(err);
192	    // Intentionally downgrade AMBIGUOUS to NOT_FOUND: the caller must not learn
193	    // that multiple repos contain this slug (prevents cross-namespace existence leak).
194	    if (msg.startsWith('NOT_FOUND') || msg.startsWith('AMBIGUOUS')) {
195	      notFound(`Project '${slug}' not found.`);
196	    }
197	    throw err;
198	  }
199	
200	  try {
201	    const raw = await readFile(join(storageDir, '.meta.json'), 'utf-8');
202	    const meta = ProjectMetaSchema.parse(JSON.parse(raw));
203	    return new LedgerStore(meta.plan_path, ledgerRoot);
204	  } catch (err) {
205	    const errMsg = err instanceof Error ? err.message : String(err);
206	    process.stderr.write(
207	      `[resolveProjectStore] Failed to read metadata for slug="${slug}"` +
208	        (repoName !== undefined ? ` repo="${repoName}"` : '') +
209	        `: ${errMsg}\n`
210	    );
211	    notFound(`Project '${slug}' not found or has no metadata.`);
212	  }
213	}
