218	
219	export interface InsightEntry {
220	  project_slug: string;
221	  project_status: ProjectStatus;
222	  type: string;
223	  priority: 'low' | 'medium' | 'high';
224	  timestamp: string;
225	  agent: string;
226	  note: string;
227	  context?: IncidentContext;
228	}
