230	/**
231	 * Aggregates all project_comments from every project ledger into a single
232	 * flat array, sorted by timestamp descending (newest first).
233	 * Per-project read failures are logged to stderr and skipped gracefully.
234	 * Returns an empty array when no projects exist or no comments are found.
235	 */
236	export async function handleGetInsights(ledgerRoot: string): Promise<InsightEntry[]> {
237	  const projects = await LedgerStore.listAllProjects(ledgerRoot);
238	
239	  const entries: InsightEntry[] = [];
240	
241	  await Promise.all(
242	    projects.map(async (meta) => {
243	      const store = new LedgerStore(meta.plan_path, ledgerRoot);
244	      let rootIndex;
245	      try {
246	        rootIndex = await store.readRootIndex();
247	      } catch (err) {
248	        process.stderr.write(
249	          `[handleGetInsights] Skipping project "${meta.slug}": ${String(err)}\n`
250	        );

251	        return;
252	      }
253	
254	      const comments = rootIndex.project_comments;
255	      if (!comments || comments.length === 0) return;
256	
257	      for (const comment of comments) {
258	        entries.push({
259	          project_slug: meta.slug,
260	          project_status: meta.status,
261	          ...comment,
262	        });
263	      }
264	    })
265	  );
266	
267	  // Sort by timestamp descending (newest first)
268	  entries.sort((a, b) => b.timestamp.localeCompare(a.timestamp));
269	
270	  return entries;
271	}
