285	/** Fields that the project list can be sorted by. */
286	export type ProjectSortField =
287	  | 'project'
288	  | 'repository'
289	  | 'status'
290	  | 'total_work_packages'
291	  | 'done'
292	  | 'date_created'
293	  | 'last_updated'
294	  | 'runner';
295	
296	/** Raw query parameters accepted by GET /api/projects. */
297	export interface ProjectListParams {
298	  page?: number | string;
299	  limit?: number | string;
300	  /** 'ACTIVE' (default), 'ALL', or a specific ProjectStatus value. */
301	  status?: string;
302	  /** Case-insensitive substring match on slug, project_name, repository_name. */
303	  search?: string;
304	  /** Sort column. Defaults to 'last_updated'. */
305	  sort?: string;
306	  /** 'asc' or 'desc'. Defaults to 'desc'. */
307	  dir?: string;
308	  /** Normalized runner filter ('orchestrator', 'vscode', 'claude-code', 'unknown'). Unrecognized values return empty results without a 500. */
309	  runner?: string;
310	}
311	
312	/** Paginated response envelope returned by handleListProjects. */
313	export interface ProjectListEnvelope {
314	  projects: ProjectSummary[];
315	  total: number;
316	  page: number;
317	  limit: number;
318	  total_pages: number;
319	  /** Per-status counts computed from the search-filtered set (before status filter). */
320	  status_counts: Record<string, number>;
321	  /** Per-runner counts computed from the search-filtered set (before runner filter). 'unknown' for projects without a stored runner field. */
322	  runner_counts: Record<string, number>;
323	}
324	
325	const SORT_FIELDS = new Set<ProjectSortField>([
326	  'project',
327	  'repository',
328	  'status',
329	  'total_work_packages',
330	  'done',
331	  'date_created',
332	  'last_updated',
333	  'runner',
334	]);
335	
336	const VALID_STATUS_FILTERS = new Set([
337	  'ACTIVE', 'ALL', 'READY', 'IN_PROGRESS', 'COMPLETE', 'BLOCKED', 'ARCHIVED', 'CANCELLED',
338	]);
339	
340	/**
341	 * Returns a paginated envelope of enriched project summaries.
342	 *
343	 * Processing pipeline:
344	 *  1. Enrich all projects (cache fast-path from .meta.json when available).
345	 *  2. Apply search filter to the full list.
346	 *  3. Compute status_counts from the search-filtered set (before status filter).
347	 *  4. Apply status filter.
348	 *  5. Sort.
349	 *  6. Paginate (slice) and return the envelope.
350	 *
351	 * project_name resolution order: manifest file → slug date-strip fallback →
352	 * meta.title (takes precedence when set).
353	 * Per-project read failures are isolated so one bad project never breaks
354	 * the entire response.
355	 */
356	export async function handleListProjects(
357	  ledgerRoot: string,
358	  rawParams: ProjectListParams = {}
359	): Promise<ProjectListEnvelope> {
360	  // --- Validate and sanitise params ---
361	  const page = Math.max(1, Math.floor(Number(rawParams.page) || 1));
362	  const limitRaw = rawParams.limit !== undefined ? Math.floor(Number(rawParams.limit)) : 50;
363	  const limit = Math.min(200, Math.max(1, isNaN(limitRaw) ? 50 : limitRaw));
364	  const statusFilter =
365	    rawParams.status !== undefined && VALID_STATUS_FILTERS.has(rawParams.status)
366	      ? rawParams.status
367	      : 'ACTIVE';
368	  const search = (rawParams.search ?? '').trim();
369	  const sortRaw = rawParams.sort ?? '';
370	  const sort: ProjectSortField = SORT_FIELDS.has(sortRaw as ProjectSortField)
371	    ? (sortRaw as ProjectSortField)
372	    : 'last_updated';
373	  const dir: 'asc' | 'desc' = rawParams.dir === 'asc' ? 'asc' : 'desc';
374	  // runner filter — undefined means no filter; any string value (including unrecognized ones) is accepted
375	  // so that unrecognized runners return an empty set rather than a 500 error.
376	  const runnerFilter: string | undefined = rawParams.runner;
377	
378	  const allProjects = await LedgerStore.listAllProjects(ledgerRoot);
379	
380	  // --- Enrich all projects ---
381	  const enrichedAll = await Promise.all(
382	    allProjects.map(async (meta): Promise<ProjectSummary> => {
383	      let total_work_packages = 0;
384	      let pending_work_packages = 0;
385	      let progress_pct = 0;
386	      let project_name: string | null = null;
387	
388	      const projectRoot = inferProjectRootFromPlanPath(meta.plan_path);
389	
390	      // Derive project name from slug first — takes precedence over any repo
391	      // manifest file (package.json etc.), which would return the repository
392	      // name rather than the individual plan's name. Strips the YYYY-MM-DD-
393	      // date prefix and title-cases the remainder, e.g.
394	      // "2026-02-27-gui-enhancements" → "Gui Enhancements".
395	      const slugMatch = meta.slug.match(/^\d{4}-\d{2}-\d{2}-(.+)$/);
396	      if (slugMatch) {
397	        project_name = slugMatch[1]
398	          .split('-')
399	          .map((w) => (w.length > 0 ? w.charAt(0).toUpperCase() + w.slice(1) : w))
400	          .join(' ');

401	      }
402	
403	      // FAST PATH: use cached enrichment values from .meta.json when available.
404	      // Falls back to I/O-based enrichment for legacy meta files that pre-date
405	      // the enrichment cache (WP-006). The cached project_name is only used
406	      // when slug derivation produced no name (non-date-prefixed slugs).
407	      if (
408	        meta.total_work_packages !== undefined &&
409	        meta.project_name !== undefined
410	      ) {
411	        total_work_packages = meta.total_work_packages;
412	        pending_work_packages = meta.pending_work_packages ?? 0;
413	        progress_pct = meta.progress_pct ?? (total_work_packages > 0
414	          ? Math.round(((total_work_packages - pending_work_packages) / total_work_packages) * 100)
415	          : 0);
416	        if (project_name === null) {
417	          project_name = meta.project_name;
418	        }
419	      } else {
420	        const store = new LedgerStore(meta.plan_path, ledgerRoot);
421	
422	        await Promise.all([
423	          (async () => {
424	            try {
425	              const rootIndex = await store.readRootIndex();
426	              total_work_packages = rootIndex.total_work_packages ?? 0;
427	              pending_work_packages = rootIndex.pending_work_packages ?? 0;
428	              progress_pct = total_work_packages > 0
429	                ? Math.round(((total_work_packages - pending_work_packages) / total_work_packages) * 100)
430	                : 0;
431	            } catch {
432	              // default to 0
433	            }
434	          })(),
435	          (async () => {
436	            // Only read the repo manifest when slug derivation produced no name.
437	            if (project_name === null) {
438	              project_name = await readProjectName(projectRoot);
439	            }
440	          })(),
441	        ]);
442	      }
443	
444	      // Persisted title takes precedence over all auto-detected names.
445	      if (meta.title && meta.title.trim().length > 0) {
446	        project_name = meta.title;
447	      }
448	
449	      // Derive repository_name from the project root directory name.
450	      const repository_name = projectRoot
451	        ? (projectRoot.split(/[\\/]/).filter(Boolean).pop() ?? null)
452	        : null;
453	
454	      return {
455	        ...meta,
456	        // Normalize runner: projects without a stored runner field default to 'unknown'
457	        // for consistent filtering and display.
458	        runner: meta.runner ?? 'unknown',
459	        total_work_packages,
460	        pending_work_packages,
461	        progress_pct,
462	        project_name,
463	        repository_name,
464	      };
465	    })
466	  );
467	
468	  // --- Step 2: Search filter (applied to full list, before status filter) ---
469	  const searchLower = search.toLowerCase();
470	  const searchFiltered = searchLower
471	    ? enrichedAll.filter(
472	        (p) =>
473	          p.slug.toLowerCase().includes(searchLower) ||
474	          (p.project_name ?? '').toLowerCase().includes(searchLower) ||
475	          (p.repository_name ?? '').toLowerCase().includes(searchLower)
