231	/**
232	 * Aggregates all project_comments from every project ledger into a single
233	 * flat array, sorted by timestamp descending (newest first).
234	 * Per-project read failures are logged to stderr and skipped gracefully.
235	 * Returns an empty array when no projects exist or no comments are found.
236	 */
237	export async function handleGetInsights(ledgerRoot: string): Promise<InsightEntry[]> {
238	  const projects = await LedgerStore.listAllProjects(ledgerRoot);
239	
240	  const entries: InsightEntry[] = [];
241	
242	  await Promise.all(
243	    projects.map(async (meta) => {
244	      const store = new LedgerStore(meta.plan_path, ledgerRoot);
245	      let rootIndex;
246	      try {
247	        rootIndex = await store.readRootIndex();
248	      } catch (err) {
249	        process.stderr.write(
250	          `[handleGetInsights] Skipping project "${meta.slug}": ${String(err)}\n`
251	        );
252	        return;
253	      }
254	
255	      const comments = rootIndex.project_comments;
256	      if (!comments || comments.length === 0) return;
257	
258	      const projectRoot = inferProjectRootFromPlanPath(meta.plan_path);
259	      const repository_name: string | null = projectRoot
260	        ? (projectRoot.split(/[\\/]/).filter(Boolean).pop() ?? null)
261	        : null;
262	
263	      for (const comment of comments) {
264	        entries.push({
265	          project_slug: meta.slug,
266	          project_status: meta.status,
267	          repository_name,
268	          ...comment,
269	        });
270	      }
271	    })
272	  );
273	
274	  // Sort by timestamp descending (newest first)
275	  entries.sort((a, b) => b.timestamp.localeCompare(a.timestamp));
276	
277	  return entries;
278	}
