 61	 *
 62	 * So calling dirname() four times on a normalized plan path returns the project root.
 63	 *
 64	 * This function is pure — it performs no filesystem access.
 65	 *
 66	 * @param planPath - Absolute path to the plan folder (e.g. "/home/user/project/docs/agents/plans/2026-02-01-feat")
 67	 * @returns The project root path (e.g. "/home/user/project")
 68	 */
 69	export function inferProjectRootFromPlanPath(planPath: string): string {
 70	  // Normalize backslashes to forward slashes for cross-platform correctness
 71	  const normalized = planPath.replace(/\\/g, '/');
 72	  // Walk up 4 levels: slug → plans → agents → docs → project-root
 73	  let current = normalized;
 74	  for (let i = 0; i < 4; i++) {
 75	    current = posix.dirname(current);
 76	  }
 77	  return current;
 78	}
